import { useState } from 'react';
import { Menu, X, MessageCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth0 } from '@auth0/auth0-react';

const LandingHeader = () => {

const { loginWithRedirect } = useAuth0();
  
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const scrollToSection = (sectionId: string) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
    setIsMenuOpen(false);
  };

  return (
    <header className="fixed top-0 w-full bg-white/95 backdrop-blur-sm z-50 border-b border-gray-100">
        <button onClick={() => loginWithRedirect()} className="btn-class">
        Iniciar Sesión
      </button>
      <div className="container mx-auto px-4 py-4">
        <nav className="flex items-center justify-between">
          {/* Logo */}
          <div className="flex items-center space-x-2">
            <MessageCircle className="h-8 w-8 text-autowhapp-blue" />
            <span className="text-xl font-bold text-autowhapp-black">Autowhapp</span>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-8">
            <button 
              onClick={() => scrollToSection('inicio')}
              className="text-gray-700 hover:text-autowhapp-blue transition-colors"
            >
              Inicio
            </button>
            <button 
              onClick={() => scrollToSection('caracteristicas')}
              className="text-gray-700 hover:text-autowhapp-blue transition-colors"
            >
              Características
            </button>
            <button 
              onClick={() => scrollToSection('precios')}
              className="text-gray-700 hover:text-autowhapp-blue transition-colors"
            >
              Precios
            </button>
            <button 
              onClick={() => scrollToSection('contacto')}
              className="text-gray-700 hover:text-autowhapp-blue transition-colors"
            >
              Contacto
            </button>
            <Button 
              onClick={() => scrollToSection('contacto')}
              className="bg-autowhapp-blue hover:bg-blue-700 text-white px-6 py-2"
            >
              Comienza Gratis
            </Button>
          </div>

          {/* Mobile Menu Button */}
          <button
            className="md:hidden"
            onClick={() => setIsMenuOpen(!isMenuOpen)}
          >
            {isMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </button>
        </nav>

        {/* Mobile Navigation */}
        {isMenuOpen && (
          <div className="md:hidden mt-4 py-4 border-t border-gray-100">
            <div className="flex flex-col space-y-4">
              <button 
                onClick={() => scrollToSection('inicio')}
                className="text-left text-gray-700 hover:text-autowhapp-blue transition-colors"
              >
                Inicio
              </button>
              <button 
                onClick={() => scrollToSection('caracteristicas')}
                className="text-left text-gray-700 hover:text-autowhapp-blue transition-colors"
              >
                Características
              </button>
              <button 
                onClick={() => scrollToSection('precios')}
                className="text-left text-gray-700 hover:text-autowhapp-blue transition-colors"
              >
                Precios
              </button>
              <button 
                onClick={() => scrollToSection('contacto')}
                className="text-left text-gray-700 hover:text-autowhapp-blue transition-colors"
              >
                Contacto
              </button>
              <Button 
                onClick={() => scrollToSection('contacto')}
                className="bg-autowhapp-blue hover:bg-blue-700 text-white w-full"
              >
                Comienza Gratis
              </Button>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default LandingHeader;